// One-off: second batch. Fire wall tick fix, and keys the code reads with a C++ default but that were missing in data.
'use strict';
const fs = require('fs');
const path = require('path');
const dir = 'C:/GameJam/Glyphbound/Content/Data';
function edit(name, fn) {
	const file = path.join(dir, name);
	const raw = fs.readFileSync(file, 'utf8');
	const crlf = raw.indexOf('\r\n') >= 0;
	const obj = JSON.parse(raw);
	fn(obj);
	let out = JSON.stringify(obj, null, '\t') + '\n';
	if (crlf) { out = out.split('\n').join('\r\n'); }
	fs.writeFileSync(file, out);
}
edit('Spells.json', (s) => {
	const sp = (id) => { const x = s.Spells.find((y) => y.Id === id); if (!x) { throw new Error(id); } return x; };
	const P = (id, param, base, min, max) => {
		sp(id).Params[param] = { Base: base, Min: min === undefined ? base : min, Max: max === undefined ? base : max, ScaledBy: (sp(id).Params[param] || {}).ScaledBy || 'None' };
	};
	// Fire wall: an orc could cross it between two 0.5 s ticks and take nothing.
	P('FireWall', 'TickInterval', 0.25); P('FireWall', 'Thickness', 100);
	P('FireWall', 'DamagePerSecond', 60, 30, 90); P('FireWall', 'BuildUp', 15);
	// Keys that existed only as C++ defaults.
	P('Fireball', 'ExplosionFalloff', 1); P('Fireball', 'HeadshotMult', 1); P('Fireball', 'Pierce', 0);
	P('LightningBolt', 'HeadshotMult', 1); P('LightningBolt', 'ProjectileGravity', 0); P('LightningBolt', 'ExplosionKnockback', 0);
	P('IceWall', 'HealthRegen', 0);
	P('Flamethrower', 'Duration', 0);
	P('LightningRune', 'FigureGlow', 1); P('IceFloor', 'FigureGlow', 1);
});
edit('Items.json', (it) => {
	const g = it.Items.find((y) => y.Id === 'ElectricGrenade');
	g.Stats.Range = 5000;
});
console.log('ok');
EOF
node "$S/apply_balance_2.js" && git diff --stat -- Glyphbound/Content/Data/Items.json Glyphbound/Content/Data/Spells.json && git diff -- Glyphbound/Content/Data/Items.json | grep -E "^[+-]" | head -30

